// =============================================================================
// Resource registry — single source of truth for list/detail/create/update
// screens. The web app renders forms and tables from GET /meta/resources, the
// API builds validation and SQL from the same definitions. Every query still
// runs under Row-Level Security; `module` drives friendly permission checks.
// =============================================================================

export type FieldType = 'text' | 'textarea' | 'number' | 'date' | 'datetime' | 'time' | 'select' | 'boolean' | 'ref' | 'tags';
export interface Opt { value: string; label: string }
export interface FieldDef {
  name: string; label: string; type: FieldType;
  required?: boolean; options?: Opt[]; ref?: string; refParams?: Record<string, string>;
  min?: number; max?: number; maxLength?: number; pattern?: string; patternMessage?: string;
  create?: boolean; update?: boolean; help?: string; default?: unknown; wide?: boolean; group?: string;
}
export interface ColumnDef { name: string; label: string; kind?: 'text' | 'date' | 'datetime' | 'status' | 'badge' | 'money' | 'number' | 'bool' }
export interface FilterDef { name: string; label: string; type: 'select' | 'ref' | 'date'; options?: Opt[]; ref?: string; refParams?: Record<string, string>; sql: string }
export interface ResourceDef {
  key: string; title: string; singular: string; module: string; table: string; alias: string;
  select: string; from: string; unitPath?: string; search: string[]; filters?: FilterDef[]; sort: string;
  columns: ColumnDef[]; fields: FieldDef[]; titleField: string;
  softDelete?: boolean; noCreate?: boolean; noUpdate?: boolean; noDelete?: boolean; workflow?: string;
  where?: string; deleteMode?: 'soft' | 'revoke'; group: string; icon?: string;
}

