// ------------------------------------------------------------------ field helpers
type FOpts = Partial<FieldDef>;
const F = {
  text: (name: string, label: string, x: FOpts = {}): FieldDef => ({ name, label, type: 'text', maxLength: 200, ...x }),
  area: (name: string, label: string, x: FOpts = {}): FieldDef => ({ name, label, type: 'textarea', maxLength: 4000, wide: true, ...x }),
  num: (name: string, label: string, x: FOpts = {}): FieldDef => ({ name, label, type: 'number', ...x }),
  date: (name: string, label: string, x: FOpts = {}): FieldDef => ({ name, label, type: 'date', ...x }),
  dt: (name: string, label: string, x: FOpts = {}): FieldDef => ({ name, label, type: 'datetime', ...x }),
  time: (name: string, label: string, x: FOpts = {}): FieldDef => ({ name, label, type: 'time', ...x }),
  sel: (name: string, label: string, options: Opt[], x: FOpts = {}): FieldDef => ({ name, label, type: 'select', options, ...x }),
  bool: (name: string, label: string, x: FOpts = {}): FieldDef => ({ name, label, type: 'boolean', ...x }),
  ref: (name: string, label: string, ref: string, x: FOpts = {}): FieldDef => ({ name, label, type: 'ref', ref, ...x }),
  tags: (name: string, label: string, x: FOpts = {}): FieldDef => ({ name, label, type: 'tags', wide: true, ...x }),
};
const cols = (spec: string): ColumnDef[] =>
  spec.split(',').map((s) => s.trim()).filter(Boolean).map((s) => { const [name, label, kind] = s.split(':'); return { name, label, kind: (kind as any) || 'text' }; });
const PHONE = { pattern: '^[0-9+() -]{6,20}$', patternMessage: 'nomor telepon tidak valid' };
const CODE = { pattern: '^[A-Z0-9_.-]{2,30}$', patternMessage: 'huruf besar/angka/._- (2–30)' };
const NIK = { pattern: '^[0-9]{16}$', patternMessage: 'NIK harus 16 digit' };
const STD = (a: string) => `${a}.version, ${a}.created_at, ${a}.updated_at`;

