    filters: [{ name: 'status', label: 'Status', type: 'select', options: OPT.encounterStatus, sql: 'e.status = $' }, { name: 'patient_id', label: 'Pasien', type: 'ref', ref: 'patient', sql: 'e.patient_id = $' },
      { name: 'icd10_code', label: 'ICD-10', type: 'ref', ref: 'icd10', sql: 'd.icd10_code = $' }],
